template.solver:
def solve(n):
    count = 0
    for d in range(1, n + 1):
        ok = True
        for r in range(1, d + 1):
            cnt = sum(1 for x in range(1, n + 1) if (x - r) % d == 0)
            if cnt % 2 != 0:
                ok = False
                break
        if ok:
            count += 1
    return count
